const html = htm.bind(h);
const dayName = (ymd) => { const d = fromYmd(ymd); return d.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' }); };
const DL = ['M', 'T', 'W', 'T', 'F', 'S', 'S']; const DI = [1, 2, 3, 4, 5, 6, 0];
