  const shrink = (file) => new Promise((res, rej) => { const img = new Image(); img.onload = () => { const max = 1600; const sc = Math.min(1, max / Math.max(img.width, img.height)); const c = document.createElement('canvas'); c.width = Math.round(img.width * sc); c.height = Math.round(img.height * sc); c.getContext('2d').drawImage(img, 0, 0, c.width, c.height); URL.revokeObjectURL(img.src); res({ data: c.toDataURL('image/jpeg', 0.8), w: c.width, h: c.height }); }; img.onerror = rej; img.src = URL.createObjectURL(file); });
