function GrantItem({ b, cfg, pin, refresh }) { const [kid, setKid] = useState(b.kids[0].id); const [item, setItem] = useState(''); return html`<div class="trow"><${Who} v=${kid} set=${setKid} kids=${b.kids} extra=${false} /><select value=${item} onChange=${(e) => setItem(e.target.value)} style="border:0;border-radius:8px;padding:6px">${cfg.wardrobe.catalog.filter((i) => i.prizeOnly || i.minLevel).map((i) => html`<option value=${i.id}>${i.value || ''} ${i.label}</option>`)}</select><button class="pill sm" onClick=${async () => { if (!item) return; await api('/api/admin/grant', { kid, stars: 0, itemId: item, note: 'prize unlock' }, pin); chime('win'); toast('Unlocked'); refresh(); }}>Unlock for ${b.kids.find((k) => k.id === kid)?.name}</button></div>`; }
function Meals({ b, refresh }) {
  const days = Array.from({ length: 14 }, (_, i) => addDays(b.calWeekStart || b.weekStart, i)); const [edit, setEdit] = useState({});
  const DN = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  return html`<h3>Dinners</h3><p style="font-size:12px;color:var(--muted);font-weight:700;margin:4px 0">Type a dinner and, if you like, its ingredients separated by commas. "Add to groceries" drops them on the list.</p>
    ${days.map((d) => { const m = b.meals.find((x) => x.date === d); const e = edit[d] || { text: m?.text || '', ingredients: m?.ingredients || '' }; return html`<div class="trow" style=${d === b.today ? { background: 'var(--note)' } : {}}><b style="width:70px">${DN[fromYmd(d).getDay()]} ${fromYmd(d).getDate()}</b><input class="nm" placeholder="Tacos" value=${e.text} onInput=${(ev) => setEdit({ ...edit, [d]: { ...e, text: ev.target.value } })} onBlur=${async () => { if (e.text !== (m?.text || '') || e.ingredients !== (m?.ingredients || '')) { await put('/api/meal', { date: d, text: e.text, ingredients: e.ingredients, who: b.me?.name || '' }); refresh(); } }} /><input class="nm" placeholder="ingredients, comma separated" value=${e.ingredients} onInput=${(ev) => setEdit({ ...edit, [d]: { ...e, ingredients: ev.target.value } })} onBlur=${async () => { await put('/api/meal', { date: d, text: e.text, ingredients: e.ingredients, who: b.me?.name || '' }); refresh(); }} />${m?.ingredients ? html`<button class="pill sm lite" onClick=${async () => { await api('/api/meal/shop', { date: d }); toast('Added to groceries'); refresh(); }}>🛒 Add to groceries</button>` : ''}</div>`; })}`;
}
function School({ cfg, update }) {
  const [d, setD] = useState('');
  return html`<h3>School days</h3><${F} label="School weekdays"><div class="dow">${DL.map((l, i) => html`<button class=${cfg.school.days.includes(DI[i]) ? 'on' : ''} onClick=${() => update((c) => { const s = new Set(c.school.days); s.has(DI[i]) ? s.delete(DI[i]) : s.add(DI[i]); c.school.days = [...s].sort(); })}>${l}</button>`)}</div></${F}>
    <${F} label="Days off (no school)"><input type="date" value=${d} onInput=${(e) => setD(e.target.value)} /><button class="pill sm" onClick=${() => { if (d) update((c) => { if (!c.school.daysOff.includes(d)) c.school.daysOff.push(d); c.school.daysOff.sort(); }); }}>Add day off</button></${F}>
    <div class="chips">${cfg.school.daysOff.map((x) => html`<button onClick=${() => update((c) => c.school.daysOff = c.school.daysOff.filter((y) => y !== x))}>${x} ×</button>`)}</div>
    ${cfg.kids.map((k, i) => html`<${F} label=${k.name + ' leaves at'}><input type="time" value=${k.leaveTime} onInput=${(e) => update((c) => c.kids[i].leaveTime = e.target.value)} /><span style="font-size:12px;color:var(--muted)">before-school list shows until then</span></${F}>`)}
    <div class="sub">Countdowns</div>${(cfg.countdowns || []).map((c, idx) => html`<div class="trow"><input class="emi" value=${c.emoji || ''} onInput=${(e) => update((x) => x.countdowns[idx].emoji = e.target.value)} /><input class="nm" value=${c.title} onInput=${(e) => update((x) => x.countdowns[idx].title = e.target.value)} /><input type="date" value=${c.date} onInput=${(e) => update((x) => x.countdowns[idx].date = e.target.value)} style="border:0;border-radius:8px;padding:6px" /><button class="x" onClick=${() => update((x) => x.countdowns.splice(idx, 1))}>×</button></div>`)}<button class="addrow" onClick=${() => update((c) => (c.countdowns = c.countdowns || []).push({ title: 'Winter break', emoji: '🎄', date: addDays(new Date().toISOString().slice(0, 10), 30) }))}>＋ Add a countdown</button>`;
}
function Calendar({ cfg, update, pin, refresh, b }) {
  const [test, setTest] = useState({});
  return html`<h3>Calendars</h3><p style="font-size:12px;color:var(--muted);font-weight:700;margin:4px 0">In Google Calendar on the web: Settings → the calendar → "Secret address in iCal format". Paste each one here. Events are refreshed every 15 minutes.</p>
    ${cfg.calendars.map((c, i) => html`<div class="trow"><input type="color" value=${c.color} onInput=${(e) => update((x) => x.calendars[i].color = e.target.value)} style="width:34px;height:34px;border:0;background:none" /><input class="nm" style="flex:0 0 110px" value=${c.name} onInput=${(e) => update((x) => x.calendars[i].name = e.target.value)} /><input class="nm" type="url" placeholder="https://calendar.google.com/calendar/ical/…/basic.ics" value=${c.url || ''} onInput=${(e) => update((x) => x.calendars[i].url = e.target.value.trim())} /><${Tog} on=${c.enabled !== false} set=${(v) => update((x) => x.calendars[i].enabled = v)} /><button class="pill sm lite" onClick=${async () => { try { const r = await api('/api/admin/test-calendar', { url: c.url }, pin); setTest({ ...test, [c.id]: `✓ ${r.events} events` }); } catch (e) { setTest({ ...test, [c.id]: '✗ ' + e.message }); } }}>Test</button><span style="font-size:12px">${test[c.id] || (b.calendarStatus[c.id] || '')}</span></div>`)}
    <button class="addrow" onClick=${() => update((c) => c.calendars.push({ id: 'cal' + uid(), name: 'New calendar', url: '', color: '#1f3a5f', owner: null, enabled: true }))}>＋ Add a calendar</button>
    <button class="pill sm lite" style="margin-top:10px" onClick=${async () => { await api('/api/admin/refresh', {}, pin); toast('Refreshed'); refresh(); }}>↻ Refresh now</button>
    <h3 style="margin-top:18px">Weather</h3><${F} label="Place name"><input type="text" value=${cfg.weather.place} onInput=${(e) => update((c) => c.weather.place = e.target.value)} /></${F}><${F} label="Latitude, longitude"><input type="number" step="0.001" value=${cfg.weather.lat} onInput=${(e) => update((c) => c.weather.lat = +e.target.value)} /><input type="number" step="0.001" value=${cfg.weather.lon} onInput=${(e) => update((c) => c.weather.lon = +e.target.value)} /></${F}>
    <${F} label="Units"><select value=${cfg.weather.units} onChange=${(e) => update((c) => c.weather.units = e.target.value)}><option value="fahrenheit">°F</option><option value="celsius">°C</option></select></${F}>
    <div class="sub">Tips (first match wins)</div>${cfg.tips.map((t, idx) => html`<div class="trow"><input class="nm" style="flex:0 0 140px" value=${t.when} onInput=${(e) => update((c) => c.tips[idx].when = e.target.value)} /><input class="nm" value=${t.text} onInput=${(e) => update((c) => c.tips[idx].text = e.target.value)} /><button class="x" onClick=${() => update((c) => c.tips.splice(idx, 1))}>×</button></div>`)}<p style="font-size:11px;color:var(--muted)">${"Rules: snow, rainPct>=40, high<40, high>80, feels<20, low<32."}</p>`;
}
function Places({ cfg, update }) {
  return html`<h3>Places and drive times</h3><p style="font-size:12px;color:var(--muted);font-weight:700;margin:4px 0">When an event's location or title contains the match word, the board shows the drive time and a leave-by time (start minus drive minus buffer). Latitude and longitude are optional and turn on the little map.</p>
    ${cfg.places.map((p, idx) => html`<div class="trow"><input class="nm" value=${p.name} onInput=${(e) => update((c) => c.places[idx].name = e.target.value)} /><input class="nm" style="flex:0 0 120px" placeholder="match word" value=${p.match || ''} onInput=${(e) => update((c) => c.places[idx].match = e.target.value)} /><label style="font-size:12px">🚗 <input type="number" style="width:50px;border:0;border-radius:8px;padding:4px" value=${p.driveMin} onInput=${(e) => update((c) => c.places[idx].driveMin = +e.target.value)} /> min</label><label style="font-size:12px">buffer <input type="number" style="width:50px;border:0;border-radius:8px;padding:4px" value=${p.bufferMin ?? 5} onInput=${(e) => update((c) => c.places[idx].bufferMin = +e.target.value)} /></label><input class="nm" style="flex:0 0 90px" type="number" step="0.0001" placeholder="lat" value=${p.lat ?? ''} onInput=${(e) => update((c) => c.places[idx].lat = e.target.value ? +e.target.value : undefined)} /><input class="nm" style="flex:0 0 90px" type="number" step="0.0001" placeholder="lon" value=${p.lon ?? ''} onInput=${(e) => update((c) => c.places[idx].lon = e.target.value ? +e.target.value : undefined)} /><button class="x" onClick=${() => update((c) => c.places.splice(idx, 1))}>×</button></div>`)}
    <button class="addrow" onClick=${() => update((c) => c.places.push({ name: 'New place', match: '', driveMin: 10, bufferMin: 5 }))}>＋ Add a place</button>`;
}
function WardrobeAdmin({ cfg, update, b }) {
  return html`<h3>Wardrobe and levels</h3><${F} label="Stars per level"><${Step} v=${cfg.rules.levelStars} set=${(v) => update((c) => c.rules.levelStars = v)} min=${20} max=${500} /></${F}>
    <${F} label="Level names"><input type="text" value=${cfg.rules.levelNames.join(', ')} onInput=${(e) => update((c) => c.rules.levelNames = e.target.value.split(',').map((s) => s.trim()).filter(Boolean))} /></${F}>
    <div class="sub">Items (cost in stars, level needed, prize-only)</div>${cfg.wardrobe.catalog.map((it, idx) => html`<div class="trow"><span style="width:80px;font-size:11px;color:var(--muted)">${it.kind}</span><span style="font-size:20px">${it.value && it.value.length <= 2 ? it.value : ''}</span><input class="nm" value=${it.label} onInput=${(e) => update((c) => c.wardrobe.catalog[idx].label = e.target.value)} /><label style="font-size:12px">★ <input type="number" style="width:50px;border:0;border-radius:8px;padding:4px" value=${it.cost} onInput=${(e) => update((c) => c.wardrobe.catalog[idx].cost = +e.target.value)} /></label><label style="font-size:12px">Lv <input type="number" style="width:44px;border:0;border-radius:8px;padding:4px" value=${it.minLevel || 0} onInput=${(e) => update((c) => c.wardrobe.catalog[idx].minLevel = +e.target.value || undefined)} /></label><label style="font-size:12px"><input type="checkbox" checked=${!!it.prizeOnly} onChange=${(e) => update((c) => c.wardrobe.catalog[idx].prizeOnly = e.target.checked)} /> prize</label></div>`)}
    <div class="sub">Each kid's base look (they change the rest themselves)</div>${b.kids.map((k) => html`<div class="trow"><${Avatar} kid=${k} size="54px" /><b>${k.name}</b><span style="font-size:12px;color:var(--muted)">owns ${k.wardrobe.owned.length} items · ★ ${k.wardrobe.balance} to spend · level ${k.level.level}</span></div>`)}`;
}
function Voice({ cfg, update }) {
  const v = cfg.voice; const [voices, setVoices] = useState([]); useEffect(() => { const load = () => { try { setVoices(rankVoices(cfg.voice.language || 'en') || []); } catch { setVoices([]); } }; load(); speechSynthesis.onvoiceschanged = load; }, [cfg.voice.language]);
  const test = (name) => { speechSynthesis.cancel(); const u = new SpeechSynthesisUtterance(`Hi! I'm the family board.${cfg.family.dog ? ' ' + cfg.family.dog + ' says hi.' : ''} Next up, swim practice at five thirty.`); const vv = name ? voices.find((x) => x.name === name) : bestVoice(); if (vv) u.voice = vv; u.rate = v.rate; u.pitch = v.pitch; speechSynthesis.speak(u); };
  const auto = bestVoice();
  return html`<h3>Voice</h3><${F} label="Wake phrase"><input type="text" value=${v.wake} onInput=${(e) => update((c) => c.voice.wake = e.target.value)} /><span style="font-size:12px;color:var(--muted)">used to trim what was heard; hands-free needs the key below</span></${F}>
    <${F} label="Hands-free listening"><${Tog} on=${!!v.handsFree} set=${(x) => update((c) => c.voice.handsFree = x)} /><span style="font-size:12px;color:var(--muted)">the board keeps the mic open and waits for the wake phrase; no account needed</span></${F}>
    <${F} label="Also accept"><input type="text" value=${v.wakeAlso || ''} onInput=${(e) => update((c) => c.voice.wakeAlso = e.target.value)} /><span style="font-size:12px;color:var(--muted)">mishearings, comma separated</span></${F}>
    <p style="font-size:12px;color:var(--muted);font-weight:700">Hands-free uses Chrome's own speech service (the same one the keyboard mic uses), so it works on the tablet out of the box. Allow the microphone once when asked. It pauses while the board is talking and during quiet hours. If the tablet ever shows a mic tone every minute or so, that is Chrome restarting the listener; turn this off and use the mic button.</p>
    <${F} label="Natural voice"><${Tog} on=${v.cloud !== false} set=${(x) => update((c) => c.voice.cloud = x)} /><span style="font-size:12px;color:var(--muted)">lifelike voices from Cloudflare; about 45 free replies a day, then the device voice takes over</span></${F}>
    ${v.cloud !== false ? html`<div class="chips" style="margin:6px 0 10px">${[['thalia', 'Thalia, bright'], ['luna', 'Luna, warm'], ['asteria', 'Asteria, clear'], ['helena', 'Helena, gentle'], ['andromeda', 'Andromeda, friendly'], ['athena', 'Athena, calm'], ['apollo', 'Apollo, cheerful'], ['arcas', 'Arcas, relaxed'], ['orion', 'Orion, steady'], ['zeus', 'Zeus, deep']].map(([id, lab]) => html`<button class=${v.cloudVoice === id ? 'on' : ''} style=${v.cloudVoice === id ? { background: '#1f3a5f', color: '#fff' } : {}} onClick=${() => { primeSpeech(); update((c) => c.voice.cloudVoice = id); cloudSpeak(`Hi ${cfg.kids.map((k) => k.name).join(' and ')}! I'm ${lab.split(',')[0]}. Next up, swim practice at five thirty.`, id).then((ok) => { if (!ok) toast('Could not load that voice right now'); }); }}>▶ ${lab}</button>`)}</div>` : ''}
    <${F} label=${v.cloud !== false ? 'Backup device voice' : 'Voice that answers'}><select value=${v.voiceName} onChange=${(e) => update((c) => c.voice.voiceName = e.target.value)}><option value="">Auto: best on this device${auto ? ' (' + auto.name + ')' : ''}</option>${voices.map((x) => html`<option value=${x.name}>${x.name} (${x.lang})${x.localService ? '' : ' · online'}</option>`)}</select><button class="pill sm lite" onClick=${() => test(v.voiceName)}>▶ Test</button></${F}>
    <div class="chips">${voices.slice(0, 6).map((x) => html`<button onClick=${() => test(x.name)}>▶ ${x.name}</button>`)}</div>
    <p style="font-size:12px;color:var(--muted);font-weight:700">Voices come from the device, so the board sounds different on the tablet than on this computer. The best ones are listed first. If every voice sounds robotic on the tablet, open Android Settings → System → Languages → Text-to-speech → Google Speech Services → Install voice data and download the "high quality" English voice; it then shows up here. Premium cloud voices (ElevenLabs, Google) can be added later for a few cents a month.</p>
    <${F} label="Speed"><input type="range" min="0.6" max="1.4" step="0.05" value=${v.rate} onInput=${(e) => update((c) => c.voice.rate = +e.target.value)} /><span>${v.rate}</span></${F}><${F} label="Pitch"><input type="range" min="0.6" max="1.6" step="0.05" value=${v.pitch} onInput=${(e) => update((c) => c.voice.pitch = +e.target.value)} /><span>${v.pitch}</span></${F}>
    <${F} label="Quiet hours"><input type="time" value=${v.quietFrom} onInput=${(e) => update((c) => c.voice.quietFrom = e.target.value)} /> to <input type="time" value=${v.quietTo} onInput=${(e) => update((c) => c.voice.quietTo = e.target.value)} /><span style="font-size:12px;color:var(--muted)">answers on screen only</span></${F}>
    <${F} label="Spoken confirmations"><${Tog} on=${v.speak} set=${(x) => update((c) => c.voice.speak = x)} /></${F}><${F} label="Listening chime"><${Tog} on=${v.chime} set=${(x) => update((c) => c.voice.chime = x)} /></${F}>
    <${F} label="Kids can by voice"><div class="chips">${[['check', 'Check off tasks'], ['claim', 'Claim quests'], ['ask', 'Ask questions'], ['grocery', 'Add groceries'], ['timer', 'Set timers']].map(([id, lab]) => html`<button class=${v.kidsCan.includes(id) ? 'on' : ''} style=${v.kidsCan.includes(id) ? { background: '#1f3a5f', color: '#fff' } : {}} onClick=${() => update((c) => { const s = new Set(c.voice.kidsCan); s.has(id) ? s.delete(id) : s.add(id); c.voice.kidsCan = [...s]; })}>${lab}</button>`)}</div></${F}>
    <${F} label="AI for unusual sentences"><${Tog} on=${v.ai} set=${(x) => update((c) => c.voice.ai = x)} /><span style="font-size:12px;color:var(--muted)">needs an ANTHROPIC_API_KEY secret on the Worker; pennies a month</span></${F}>
    <${F} label="Language"><select value=${v.language} onChange=${(e) => update((c) => c.voice.language = e.target.value)}><option value="en-US">English</option><option value="es-ES">Español</option></select></${F}>`;
}
function Settings({ cfg, update, b, pin }) {
  const [p1, setP1] = useState(''); const [gate, setGate] = useState(null); const [newCode, setNewCode] = useState(''); useEffect(() => { api('/api/admin/gate', undefined, pin).then(setGate).catch(() => {}); }, []);
  return html`<h3>Settings</h3><${F} label="Setup"><button class="pill sm lite" onClick=${() => { if (confirm('Run the setup steps again? Chores, stars and history stay.')) { update((c) => { c.setup = { done: false }; }); setTimeout(() => location.reload(), 1200); } }}>✨ Run setup again</button></${F}><${F} label="Family name"><input type="text" value=${cfg.family.name} onInput=${(e) => update((c) => c.family.name = e.target.value)} /></${F}><${F} label="Dog"><input type="text" value=${cfg.family.dog} onInput=${(e) => update((c) => c.family.dog = e.target.value)} /></${F}>
    <div class="sub">Who is each event for?</div><p style="font-size:12px;color:var(--muted);font-weight:700;margin:2px 0 6px">The board reads event titles. A person's name, or any of their keywords as a whole word, gives the event their color. Words like "the kids" mean all the kids (edit them below). Anything else shows as Family.</p>
    ${cfg.kids.map((k, i) => html`<${F} label=${'Kid ' + (i + 1)}><input type="text" style="flex:0 0 110px" value=${k.name} onInput=${(e) => update((c) => c.kids[i].name = e.target.value)} /><input type="text" placeholder="keywords, e.g. violin, strings" value=${(k.match || []).join(', ')} onInput=${(e) => update((c) => c.kids[i].match = e.target.value.split(',').map((x) => x.trim()).filter(Boolean))} /><input type="color" value=${k.color} onInput=${(e) => update((c) => c.kids[i].color = e.target.value)} /><input type="number" style="width:60px" value=${k.age} onInput=${(e) => update((c) => c.kids[i].age = +e.target.value)} /></${F}>`)}
    ${cfg.family.parents.map((p, i) => html`<${F} label=${'Parent ' + (i + 1)}><input type="text" style="flex:0 0 110px" value=${p.name} onInput=${(e) => update((c) => c.family.parents[i].name = e.target.value)} /><input type="text" placeholder="keywords, e.g. their first name, yoga" value=${(p.match || []).join(', ')} onInput=${(e) => update((c) => c.family.parents[i].match = e.target.value.split(',').map((s) => s.trim()).filter(Boolean))} /><input type="color" value=${p.color} onInput=${(e) => update((c) => c.family.parents[i].color = e.target.value)} /></${F}>`)}
    <${F} label="Time zone"><input type="text" value=${cfg.zone} onInput=${(e) => update((c) => c.zone = e.target.value)} /></${F}>

    <${F} label="Undo window (seconds)"><${Step} v=${cfg.rules.undoSeconds} set=${(v) => update((c) => c.rules.undoSeconds = v)} max=${120} /></${F}>
    <${F} label="Ambient after (minutes)"><${Step} v=${cfg.ambient.idleMinutes} set=${(v) => update((c) => c.ambient.idleMinutes = v)} min=${1} max=${30} /></${F}>
    <${F} label="Week on screensaver"><${Tog} on=${cfg.ambient.showWeek !== false} set=${(v) => update((c) => c.ambient.showWeek = v)} /><span style="font-size:12px;color:var(--muted)">the next 7 days across the bottom</span></${F}>
    <${F} label="Colors"><select value=${cfg.theme?.mode || 'sun'} onChange=${(e) => update((c) => { c.theme = { ...(c.theme || {}), mode: e.target.value }; })}><option value="sun">🌗 Follow the sun: dark after sunset</option><option value="light">☀️ Always light</option><option value="dark">🌙 Always dark</option></select><span style="font-size:12px;color:var(--muted)">${b.weather?.days?.[0] ? `today's sunset ${b.weather.days.find((x) => x.date === b.today)?.sunset || '19:00'}, sunrise ${b.weather.days.find((x) => x.date === addDays(b.today, 1))?.sunrise || '07:00'}` : 'set your town for exact sunset times'}</span></${F}>
    <${F} label="Night mode"><${Tog} on=${cfg.ambient.dimAtNight} set=${(v) => update((c) => c.ambient.dimAtNight = v)} /><input type="time" value=${cfg.ambient.sleepFrom} onInput=${(e) => update((c) => c.ambient.sleepFrom = e.target.value)} /> to <input type="time" value=${cfg.ambient.sleepTo} onInput=${(e) => update((c) => c.ambient.sleepTo = e.target.value)} /><span style="font-size:12px;color:var(--muted)">kitchen display goes dark after a quiet minute</span></${F}>
    <${F} label="Good morning screen"><${Tog} on=${cfg.ambient.morning !== false} set=${(v) => update((c) => c.ambient.morning = v)} /><span style="font-size:12px;color:var(--muted)">from ${cfg.ambient.sleepTo || '06:00'} until someone taps "Let's go"</span></${F}>
    ${cfg.ambient.morning !== false ? html`<${F} label="Morning screen days"><div class="dow">${DL.map((l, i) => { const days = cfg.ambient.morningDays || [0, 1, 2, 3, 4, 5, 6]; return html`<button class=${days.includes(DI[i]) ? 'on' : ''} onClick=${() => update((c) => { const st = new Set(c.ambient.morningDays || [0, 1, 2, 3, 4, 5, 6]); st.has(DI[i]) ? st.delete(DI[i]) : st.add(DI[i]); c.ambient.morningDays = [...st].sort(); })}>${l}</button>`; })}</div></${F}>` : ''}
    <${F} label="Preview"><button class="pill sm lite" onClick=${() => { try { localStorage.removeItem('fb-gm-done'); } catch {} window.dispatchEvent(new Event('fb-preview-morning')); }}>☀️ Show the morning screen</button><button class="pill sm lite" onClick=${() => window.dispatchEvent(new Event('fb-preview-night'))}>🌙 Show night mode</button></${F}>
    <${F} label="New PIN"><input type="password" inputmode="numeric" maxlength="4" value=${p1} onInput=${(e) => setP1(e.target.value)} /><button class="pill sm" onClick=${() => { if (/^\d{4}$/.test(p1)) { update((c) => c.pin = p1); sessionStorage.setItem('pin', p1); toast('PIN changed'); setP1(''); } else toast('4 digits'); }}>Change</button></${F}>
    ${b.auth?.enabled ? html`<${F} label="Sign-in"><span style="font-weight:800;color:#2f8f5b">On. Manage it in Sign-in and devices.</span></${F}>` : html`<${F} label="Family code"><b style="font-family:var(--head);font-size:22px;letter-spacing:.2em">${gate ? gate.code : '…'}</b><span style="font-size:12px;color:var(--muted)">typed once per device to open the board</span></${F}>
    <${F} label="Change family code"><input type="text" inputmode="numeric" maxlength="8" value=${newCode} onInput=${(e) => setNewCode(e.target.value)} /><button class="pill sm" onClick=${async () => { try { await api('/api/admin/gate', { code: newCode }, pin); toast('Family code changed'); setGate({ code: newCode }); setNewCode(''); } catch (e) { toast(e.message); } }}>Change</button></${F}>`}
    <p style="font-size:11px;color:var(--muted);margin-top:18px">Avatars: Adventurer by Lisa Wischofsky (CC BY 4.0) via DiceBear. Dog drawing: from OpenMoji (CC BY-SA 4.0). Weather: Open-Meteo. Maps: OpenStreetMap.</p>`;
}
